    const NODE_KINDS = ['sun','cloud','rain-cloud','thunderstorm','snow-cloud','wind','high-pressure','low-pressure','warm-front','cold-front','occluded-front','stationary-front','isobar','cyclone','anticyclone','thermometer','hygrometer','anemometer','rain-gauge','weather-station','mountain','sea','land','atmospheric-layer'];
    const CHART_KINDS = ['climate-graph','station-model','atmospheric-profile'];
