    function objectBox(o){if(['weather-node','weather-zone','weather-chart','weather-label'].includes(o.type))return{x:o.x,y:o.y,w:o.width,h:o.height};if(['weather-link','weather-arrow'].includes(o.type))return{x:Math.min(o.x1||0,o.x2||0),y:Math.min(o.y1||0,o.y2||0),w:Math.max(1,Math.abs((o.x2||0)-(o.x1||0))),h:Math.max(1,Math.abs((o.y2||0)-(o.y1||0)))};if(o.type==='text')return{x:o.x,y:o.y-o.fontSize,w:Math.max(100,String(o.text||'').length*o.fontSize*.55),h:o.fontSize+10};return null;}
    function portPoint(o,port){const b=objectBox(o)||{x:0,y:0,w:0,h:0};const map={n:[.5,0],ne:[1,0],e:[1,.5],se:[1,1],s:[.5,1],sw:[0,1],w:[0,.5],nw:[0,0]};const[px,py]=map[port]||map.e;return{x:b.x+b.w*px,y:b.y+b.h*py};}
    function pointerPoint(event){const rect=state.svg.getBoundingClientRect(),vb=state.svg.viewBox.baseVal;return{x:(event.clientX-rect.left)*vb.width/rect.width+vb.x,y:(event.clientY-rect.top)*vb.height/rect.height+vb.y};}
    function findObjectFromTarget(target){const hit=target.closest?.('[data-weather-hit-object]');if(hit)return objectById(hit.getAttribute('data-weather-hit-object'));const node=target.closest?.('[data-qmx-object]');return node?objectById(node.getAttribute('data-qmx-object')):null;}
    function createToolObject(tool,p){if(NODE_KINDS.includes(tool))return makeNode(tool,{x:snap(p.x-75),y:snap(p.y-48)});if(tool==='weather-zone')return makeZone({x:snap(p.x-250),y:snap(p.y-170)});if(CHART_KINDS.includes(tool))return makeChart(tool,{x:snap(p.x-270),y:snap(p.y-280)});if(tool==='process-arrow')return makeArrow({x1:snap(p.x-140),y1:snap(p.y),x2:snap(p.x+140),y2:snap(p.y)});if(tool==='text')return makeText({x:snap(p.x),y:snap(p.y)});return null;}
    function selectionMarkup(){const parts=[];if(state.activeTool==='select')state.document.objects.forEach((o)=>{const id=esc(o.id),b=objectBox(o);if(['weather-link','weather-arrow'].includes(o.type)){const a=resolveLinkEndpoints(o);parts.push(`<line class="qmx-weather-hit" data-weather-hit-object="${id}" x1="${a.x1}" y1="${a.y1}" x2="${a.x2}" y2="${a.y2}" stroke="transparent" stroke-width="24" pointer-events="stroke"/>`);}else if(b)parts.push(`<rect class="qmx-weather-hit" data-weather-hit-object="${id}" x="${b.x}" y="${b.y}" width="${Math.max(12,b.w)}" height="${Math.max(12,b.h)}" fill="transparent" stroke="none" pointer-events="all"/>`);});if(['smart-label','smart-link'].includes(state.activeTool))targetObjects().forEach((o)=>PORTS.forEach((port)=>{const p=portPoint(o,port),active=(state.labelStart?.objectId===o.id&&state.labelStart?.port===port)||(state.linkStart?.objectId===o.id&&state.linkStart?.port===port);parts.push(`<circle data-weather-target="${esc(o.id)}" data-weather-port="${port}" cx="${p.x}" cy="${p.y}" r="7.5" fill="${active?'#f59e0b':'#22c55e'}" stroke="#fff" stroke-width="2" style="cursor:crosshair"/>`);}));const o=selectedObject(),b=o&&objectBox(o);if(b)parts.push(`<rect x="${b.x-7}" y="${b.y-7}" width="${Math.max(14,b.w+14)}" height="${Math.max(14,b.h+14)}" fill="none" stroke="#2563eb" stroke-width="2" stroke-dasharray="7 5" pointer-events="none"/>`);return parts.join('');}
    function resolveLinkEndpoints(o){const source=objectById(o.sourceId),target=objectById(o.targetId),a=source?portPoint(source,o.sourcePort):{x:o.x1||0,y:o.y1||0},b=target?portPoint(target,o.targetPort):{x:o.x2||0,y:o.y2||0};return{x1:a.x,y1:a.y,x2:b.x,y2:b.y};}
    function render(){if(!state.canvas||!state.document)return;state.document=Diagram.normalizeSpec(state.document);let svg=Diagram.svgMarkup(state.document);svg=svg.replace('</svg>',`${selectionMarkup()}</svg>`);state.canvas.innerHTML=svg;state.svg=state.canvas.querySelector('svg');syncSelectedControls();updateSummary();}
    function pushHistory(){const value=JSON.stringify(state.document);if(state.history[state.historyIndex]===value)return;state.history=state.history.slice(0,state.historyIndex+1);state.history.push(value);if(state.history.length>80)state.history.shift();state.historyIndex=state.history.length-1;updateHistoryButtons();}
    function restoreHistory(index){if(index<0||index>=state.history.length)return;state.historyIndex=index;state.document=Diagram.normalizeSpec(JSON.parse(state.history[index]));state.selectedId=null;state.labelStart=null;state.linkStart=null;state.interaction=null;syncDocumentControls();render();updateHistoryButtons();}
    function undo(){restoreHistory(state.historyIndex-1);}function redo(){restoreHistory(state.historyIndex+1);}function updateHistoryButtons(){if(state.controls.undo)state.controls.undo.disabled=state.historyIndex<=0;if(state.controls.redo)state.controls.redo.disabled=state.historyIndex>=state.history.length-1;}
    function setStatus(message){if(state.controls.status)state.controls.status.textContent=message||'';}
    function setTool(tool,announce=true){state.activeTool=tool;state.labelStart=null;state.linkStart=null;state.controls.tools?.querySelectorAll('[data-tool]').forEach((b)=>b.classList.toggle('active',b.dataset.tool===tool));if(announce)setStatus(tool==='smart-label'?'Click a component connection point, then click the label position.':tool==='smart-link'?'Click a source connection point, then a target connection point.':`${tool} selected.`);render();}
    function updateSummary(){if(!state.controls.summary)return;const c={nodes:0,zones:0,pyramids:0,links:0,labels:0,arrows:0};state.document.objects.forEach((o)=>{if(o.type==='weather-node')c.nodes++;else if(o.type==='weather-zone')c.zones++;else if(o.type==='weather-chart')c.pyramids++;else if(o.type==='weather-link')c.links++;else if(o.type==='weather-label')c.labels++;else if(o.type==='weather-arrow')c.arrows++;});state.controls.summary.innerHTML=`<strong>Objects</strong><br>Weather symbols: ${c.nodes}<br>Zones: ${c.zones}<br>Charts: ${c.pyramids}<br>Atmospheric links: ${c.links}<br>Labels: ${c.labels}<br>Process arrows: ${c.arrows}<br>Total: ${state.document.objects.length}`;}
    function field(label,key,value,type='text',extra=''){return`<div class="qmx-weather-field"><label>${esc(label)}</label><input type="${type}" data-prop="${key}" value="${esc(value)}" ${extra}></div>`;}
    function textareaField(label,key,value){return`<div class="qmx-weather-field"><label>${esc(label)}</label><textarea data-prop="${key}">${esc(value)}</textarea></div>`;}
    function selectField(label,key,value,options){return`<div class="qmx-weather-field"><label>${esc(label)}</label><select data-prop="${key}">${options.map(([v,l])=>`<option value="${esc(v)}"${String(v)===String(value)?' selected':''}>${esc(l)}</option>`).join('')}</select></div>`;}
    function syncSelectedControls(){const host=state.controls.selected;if(!host)return;const o=selectedObject();if(!o){host.innerHTML='<p class="qmx-weather-muted">Select an object to edit its properties.</p>';return;}let html=`<div class="qmx-weather-object-type">${esc(o.type)}</div>`;if(o.type==='weather-node')html+=selectField('Weather feature','kind',o.kind,NODE_KINDS.map(k=>[k,k.replace(/-/g,' ').replace(/\b\w/g,m=>m.toUpperCase())]))+field('Label','label',o.label)+`<div class="qmx-weather-grid2">${field('X','x',o.x,'number')}${field('Y','y',o.y,'number')}${field('Width','width',o.width,'number')}${field('Height','height',o.height,'number')}${field('Altitude / level','level',o.level,'number')}${field('Weather value','value',o.value,'number')}${field('Secondary value','secondaryValue',o.secondaryValue,'number')}${field('Fill','fill',o.fill,'color')}${field('Stroke','stroke',o.stroke,'color')}</div>`;else if(o.type==='weather-zone')html+=field('Region title','label',o.label)+`<label class="qmx-weather-check"><input type="checkbox" data-prop="dashed"${o.dashed?' checked':''}> Dashed border</label><div class="qmx-weather-grid2">${field('X','x',o.x,'number')}${field('Y','y',o.y,'number')}${field('Width','width',o.width,'number')}${field('Height','height',o.height,'number')}${field('Fill','fill',o.fill,'color')}${field('Stroke','stroke',o.stroke,'color')}</div>`;else if(o.type==='weather-chart')html+=selectField('Chart type','kind',o.kind,CHART_KINDS.map(k=>[k,k.replace(/-/g,' ')]))+field('Title','title',o.title)+textareaField('Data — one label|value per line','levels',o.levels)+field('Unit','unit',o.unit)+`<div class="qmx-weather-grid2">${field('X','x',o.x,'number')}${field('Y','y',o.y,'number')}${field('Width','width',o.width,'number')}${field('Height','height',o.height,'number')}${field('Fill','fill',o.fill,'color')}${field('Stroke','stroke',o.stroke,'color')}</div>`;else if(o.type==='weather-link')html+=selectField('Link type','kind',o.kind,[['airflow','Airflow'],['moisture','Moisture transport'],['radiation','Radiation / heat'],['front','Front movement']])+field('Label','label',o.label)+field('Value','value',o.value,'number')+`<label class="qmx-weather-check"><input type="checkbox" data-prop="dashed"${o.dashed?' checked':''}> Dashed link</label><label class="qmx-weather-check"><input type="checkbox" data-prop="showArrow"${o.showArrow?' checked':''}> Arrowhead</label><div class="qmx-weather-grid2">${field('Stroke','stroke',o.stroke,'color')}${field('Line width','lineWidth',o.lineWidth,'number','step="0.1"')}</div>`;else if(o.type==='weather-label')html+=field('Label text','text',o.text)+selectField('Target port','targetPort',o.targetPort,PORTS.map(p=>[p,p.toUpperCase()]))+`<div class="qmx-weather-grid2">${field('X','x',o.x,'number')}${field('Y','y',o.y,'number')}${field('Width','width',o.width,'number')}${field('Height','height',o.height,'number')}${field('Fill','fill',o.fill,'color')}${field('Stroke','stroke',o.stroke,'color')}</div>`;else if(o.type==='weather-arrow')html+=field('Arrow label','label',o.label)+`<label class="qmx-weather-check"><input type="checkbox" data-prop="dashed"${o.dashed?' checked':''}> Dashed line</label><div class="qmx-weather-grid2">${field('X1','x1',o.x1,'number')}${field('Y1','y1',o.y1,'number')}${field('X2','x2',o.x2,'number')}${field('Y2','y2',o.y2,'number')}${field('Stroke','stroke',o.stroke,'color')}${field('Line width','lineWidth',o.lineWidth,'number','step="0.1"')}</div>`;else if(o.type==='text')html+=textareaField('Text','text',o.text)+`<div class="qmx-weather-grid2">${field('X','x',o.x,'number')}${field('Y','y',o.y,'number')}${field('Font size','fontSize',o.fontSize,'number')}${field('Color','color',o.color,'color')}</div>`;host.innerHTML=html;}
    function syncDocumentControls(){if(!state.root||!state.document)return;state.root.querySelectorAll('[data-doc]').forEach((input)=>{const key=input.dataset.doc;if(input.type==='checkbox')input.checked=Boolean(state.document[key]);else input.value=state.document[key]??'';});}
    function onRootChange(event){const docInput=event.target.closest?.('[data-doc]');if(docInput){const key=docInput.dataset.doc;state.document[key]=docInput.type==='checkbox'?docInput.checked:(docInput.type==='number'?num(docInput.value,state.document[key]):docInput.value);pushHistory();render();return;}const prop=event.target.closest?.('[data-prop]');if(!prop)return;const o=selectedObject();if(!o)return;const key=prop.dataset.prop;o[key]=prop.type==='checkbox'?prop.checked:(prop.type==='number'?num(prop.value,o[key]):prop.value);if(o.type==='weather-node'&&key==='kind'){const [fill,stroke]=nodeStyle(o.kind),[width,height]=defaultSize(o.kind);o.fill=fill;o.stroke=stroke;o.width=width;o.height=height;o.label=o.kind.replace(/-/g,' ');}if(o.type==='weather-chart'&&key==='kind'){const n=makeChart(o.kind);o.title=n.title;o.unit=n.unit;}pushHistory();render();}
    function deleteSelected(){const o=selectedObject();if(!o)return;const id=o.id;state.document.objects=state.document.objects.filter((x)=>x.id!==id&&!(x.type==='weather-label'&&x.targetId===id)&&!(x.type==='weather-link'&&(x.sourceId===id||x.targetId===id)));state.selectedId=null;pushHistory();render();setStatus('Selected object deleted.');}
    function duplicateSelected(){const o=selectedObject();if(!o)return;const c=clone(o);c.id=uid(o.type);if('x'in c)c.x+=30;if('y'in c)c.y+=30;if('x1'in c){c.x1+=30;c.x2+=30;c.y1+=30;c.y2+=30;}if(c.type==='weather-label')c.targetId='';if(c.type==='weather-link'){c.sourceId='';c.targetId='';}state.document.objects.push(c);state.selectedId=c.id;pushHistory();render();}
    function newDocument(){state.document=createDocument();state.selectedId=null;state.labelStart=null;state.linkStart=null;pushHistory();syncDocumentControls();render();setStatus('New weather diagram created.');}
    function onCanvasPointerDown(event){if(!state.svg||event.button>0)return;const handle=event.target.closest?.('[data-weather-target]');if(handle&&state.activeTool==='smart-label'){state.labelStart={objectId:handle.dataset.weatherTarget,port:handle.dataset.weatherPort};setStatus('Target point selected. Click where the label should appear.');render();event.preventDefault();return;}if(handle&&state.activeTool==='smart-link'){if(!state.linkStart){state.linkStart={objectId:handle.dataset.weatherTarget,port:handle.dataset.weatherPort};setStatus('Source selected. Click a target connection point.');render();}else{const targetId=handle.dataset.weatherTarget,targetPort=handle.dataset.weatherPort;if(targetId!==state.linkStart.objectId){const link=makeLink(state.linkStart.objectId,state.linkStart.port,targetId,targetPort);state.document.objects.push(link);state.selectedId=link.id;state.linkStart=null;pushHistory();setTool('select',false);render();setStatus('Smart geological link created.');}}event.preventDefault();return;}const p=pointerPoint(event);if(state.activeTool==='smart-label'&&state.labelStart){const target=objectById(state.labelStart.objectId);if(target){const l=makeLabel(target.id,state.labelStart.port,{x:snap(p.x),y:snap(p.y),text:target.label||target.kind||'Weather feature'});state.document.objects.push(l);state.selectedId=l.id;state.labelStart=null;pushHistory();setTool('select',false);render();setStatus('Smart label created.');}event.preventDefault();return;}if(state.activeTool!=='select'){const o=createToolObject(state.activeTool,p);if(o){state.document.objects.push(o);state.selectedId=o.id;pushHistory();setTool('select',false);render();setStatus('Object added and selected.');}event.preventDefault();return;}const o=findObjectFromTarget(event.target);if(!o){state.selectedId=null;render();return;}state.selectedId=o.id;const b=objectBox(o),resolved=['weather-link'].includes(o.type)?resolveLinkEndpoints(o):null;state.interaction={id:o.id,pointerId:event.pointerId,start:p,origin:b?{x:b.x,y:b.y}:null,line:['weather-link','weather-arrow'].includes(o.type)?{x1:resolved?.x1??o.x1,y1:resolved?.y1??o.y1,x2:resolved?.x2??o.x2,y2:resolved?.y2??o.y2}:null,moved:false};render();setStatus('Object selected. Drag anywhere inside its blue selection area to move.');event.preventDefault();}
    function onPointerMove(event){if(!state.interaction||!state.svg||event.pointerId!==state.interaction.pointerId)return;const o=objectById(state.interaction.id);if(!o)return;const p=pointerPoint(event),dx=p.x-state.interaction.start.x,dy=p.y-state.interaction.start.y;if(Math.abs(dx)+Math.abs(dy)<1)return;state.interaction.moved=true;if(['weather-link','weather-arrow'].includes(o.type)){if(o.type==='weather-link'){o.sourceId='';o.targetId='';}o.x1=snap(state.interaction.line.x1+dx);o.x2=snap(state.interaction.line.x2+dx);o.y1=snap(state.interaction.line.y1+dy);o.y2=snap(state.interaction.line.y2+dy);}else if('x'in o&&'y'in o&&state.interaction.origin){o.x=snap(state.interaction.origin.x+dx);o.y=snap(state.interaction.origin.y+dy);}render();event.preventDefault();}
    function onPointerUp(event){if(!state.interaction||event.pointerId!==state.interaction.pointerId)return;const moved=state.interaction.moved;state.interaction=null;if(moved){pushHistory();setStatus('Object moved; attached links and labels updated automatically.');}render();}
    function onKeydown(event){if(state.root?.hidden)return;if(event.key==='Escape'){if(state.labelStart||state.linkStart){state.labelStart=null;state.linkStart=null;render();}else close();}else if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();event.shiftKey?redo():undo();}else if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='y'){event.preventDefault();redo();}else if(event.key==='Delete'||event.key==='Backspace'){const tag=event.target?.tagName;if(!['INPUT','TEXTAREA','SELECT'].includes(tag)){event.preventDefault();deleteSelected();}}}
    function safeFilename(value){return String(value||'weather-climate-diagram').replace(/[^a-z0-9-_]+/gi,'-').replace(/^-+|-+$/g,'').toLowerCase()||'weather-climate-diagram';}
    function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},0);}
